<?php if(Yii::$app->user->identity->role==='superadmin' && !empty($archivedHemisCount)): ?><div class="alert warning">Bazadagi <?= (int)$archivedHemisCount ?> ta HEMIS hisobi o‘chirilgan holatda. Xodimlarni import qilsangiz, HEMISda mavjud hisoblar faol O‘qituvchi sifatida qaytadi.</div><?php endif ?><div class="page-heading"><div><span class="eyebrow">TASHQI MA’LUMOTLAR</span><h1>HEMIS integratsiyasi</h1><p>Tashkilot tuzilmasi va xodimlarni rasmiy API orqali yuklang.</p></div></div><div class="form-grid"><section class="card"><h2>Ulanish sozlamalari</h2><?= Html::beginForm(['admin/hemis'],'post') ?><?= Html::hiddenInput('operation','configure') ?><?= Ui::input('HEMIS domeni','host',$settings['host']??'','text',['required'=>true,'placeholder'=>'hemis.universitet.uz']) ?><?= Ui::input('API kaliti (saqlanganni qoldirish uchun bo‘sh qoldiring)','token','','password',['autocomplete'=>'new-password']) ?><p class="muted"><?= empty($settings['token'])?'API kaliti hali saqlanmagan.':'API kaliti saqlangan. Xavfsizlik uchun maydon bosh korsatiladi. Bosh qoldirsangiz oldingi kalit saqlanadi.' ?></p><button class="button">Sozlamalarni saqlash</button><?= Html::endForm() ?></section><aside class="card form-note"><h2>Import tartibi</h2><p>Avval tuzilmani, keyin xodimlarni yuklang. Mavjud yozuvlar HEMIS identifikatori bilan yangilanadi.</p><p>Yangi va o‘chirilgan HEMIS hisoblari faol O‘qituvchi roli bilan yaratiladi yoki tiklanadi. Keyin rolni superadministrator o‘zgartiradi. Yangi hisobning vaqtinchalik parolini administrator belgilaydi.</p><p>HEMIS administratori API kaliti bilan bergan backend domenidan foydalaning. Student kabineti domeni REST API domenidan farq qilishi mumkin.</p><p>Domen server tarmoq ruxsatlarida ochiq bo‘lishi kerak. Kalitni chatga yubormang.</p></aside></div><section class="card"><h2>Ma’lumotlarni yuklash</h2><div class="actions"><?php foreach(['test'=>'Ulanishni tekshirish','structure'=>'Tuzilmani import qilish','employees'=>'Xodimlarni import qilish'] as $op=>$label): if($op!=='test' && Yii::$app->user->identity->role!=='superadmin')continue; ?><?= Html::beginForm(['admin/hemis'],'post') ?><?= Html::hiddenInput('operation',$op) ?><?php if($op==='employees'): ?><div id="employee-import"><p class="muted">O‘chirilgan hisoblar avtomatik faol O‘qituvchi sifatida tiklanadi. Eski ID, parol va hujjatlar saqlanadi.</p></div><?php endif ?><?php if($op==='structure'): ?><?= Ui::select('Universitet','university_id','',array_column($universities,'name','id'),['required'=>true]) ?><?php endif ?><button class="button secondary"><?= Ui::h($label) ?></button><?= Html::endForm() ?><?php endforeach ?></div><p class="muted">Import mavjud faol hisoblarning qo‘lda berilgan roli va parolini saqlaydi. O‘chirilgan hisoblar faol O‘qituvchi sifatida qaytadi. Qo‘lda bloklangan hisoblar avtomatik ochilmaydi. Pasport va JSHIR ma’lumotlari olinmaydi.</p></section>

<?php if(!empty($lastImport)): ?><section class="card"><h2>Oxirgi xodimlar importi</h2><p class="muted"><?= Ui::h($lastImport['finished_at']??'') ?></p><dl class="details"><?php foreach(['received'=>'HEMISdan olingan','created'=>'Yangi hisob','updated'=>'Yangilangan','restored'=>'Faol tiklangan','activated'=>'Oldingi importdan faollashtirilgan','unique_users'=>'Ro‘yxatga yozilgan xodimlar','skipped'=>'O‘tkazilgan','unlinked'=>'Bo‘limga bog‘lanmagan'] as $key=>$label): if($key==='unique_users' && !array_key_exists($key,$lastImport))continue; ?><div><dt><?= Ui::h($label) ?></dt><dd><?= (int)($lastImport[$key]??0) ?></dd></div><?php endforeach ?></dl><?php foreach($lastImport['reasons']??[] as $reason=>$count): ?><p><?= Ui::h($reason) ?>: <?= (int)$count ?></p><?php endforeach ?><p class="muted">Yangi va tiklangan hisoblar faol O‘qituvchi sifatida ro‘yxatda ko‘rinadi. Yangi hisob uchun vaqtinchalik parol va KPI toifasini belgilang. Rollarni faqat superadministrator o‘zgartiradi.</p></section><?php endif ?>
